import { field, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "frRootSize", label: "Root font size (html)", type: "number", value: "16", help: "Default browser value is 16px" })}${select({ id: "frUnit", label: "Root-relative unit", options: [{label:"rcap — cap height (uppercase letter)",value:"rcap"},{label:"rch — character width (width of '0')",value:"rch"},{label:"rex — x-height (lowercase letter)",value:"rex"},{label:"ric — ideograph width (CJK character)",value:"ric"}], value: "rcap" })}</div><div class="field-grid">${field({ id: "frValue", label: "Value in the unit", type: "number", value: "2.5", help: "e.g. 2.5rcap — calculated from root font size" })}${field({ id: "frProperty", label: "CSS property", value: "font-size", help: "Property to apply the calculated value to" })}</div><div class="field-grid">${field({ id: "frSelector", label: "Selector", value: ".heading" })}${checkbox({ id: "frCompare", label: "Show comparison with other units", checked: true })}</div>`,generate(root) {const rootSize = parseFloat(root.querySelector("#frRootSize").value) || 16;const unit = root.querySelector("#frUnit").value;const value = parseFloat(root.querySelector("#frValue").value) || 2.5;const property = root.querySelector("#frProperty").value.trim() || "font-size";const selector = root.querySelector("#frSelector").value.trim() || ".heading";const compare = root.querySelector("#frCompare").checked;const unitApprox = {rcap: rootSize * 0.67,rch: rootSize * 0.5,rex: rootSize * 0.5,ric: rootSize,};const pxValue = (value * unitApprox[unit]).toFixed(1);const lines = [];lines.push("/* CSS Root-Relative Font Units — Baseline 2026 */");lines.push("/* Browser support: Chrome 131+, Edge 131+, Safari 18.2+, Firefox 136+ */");lines.push("/* These units are relative to the root element's font metrics, not the current element. */");lines.push("");lines.push(`${selector} {`);lines.push(` ${property}: ${value}${unit};`);lines.push(` /* Approximate computed value: ~${pxValue}px (based on ${rootSize}px root font size) */`);lines.push(`}`);lines.push("");const unitDescriptions = {rcap: "/* rcap: Root Cap height — height of uppercase letters (e.g., 'H', 'M') on the root element. */",rch: "/* rch: Root Character width — width of the '0' (zero) glyph on the root element. */",rex: "/* rex: Root Ex — x-height of the root element's font (height of lowercase 'x'). */",ric: "/* ric: Root Ideograph — width of CJK water ideograph (水) on the root element. */"};lines.push(unitDescriptions[unit]);lines.push("");lines.push("/* Unlike rem (which uses the root font-size), these units reference specific font metrics: */");lines.push("/* rem: root em-square rcap: root cap height rex: root x-height */");lines.push("/* rch: root character width ric: root ideograph width */");if (compare) {lines.push("");lines.push("/* Comparison with equivalent units: */");const remVal = `${value}rem`;lines.push(`/* ${value}rem — ${(value * rootSize).toFixed(1)}px (same as current element's rem, not root metrics) */`);lines.push(`/* ${value}rcap — ~${pxValue}px (scales with root font's capital letter height) */`);}const barStyles = [{ label: `${value}rem`, width: Math.round(value * rootSize), color: "#3b82f6" },{ label: `${value}${unit}`, width: Math.round(parseFloat(pxValue)), color: "#f59e0b" },];const bars = barStyles.map(b => `<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px"><span style="font-size:11px;font-family:monospace;width:70px;text-align:right;color:#6b7280">${b.label}</span><div style="flex:1;background:#e5e7eb;border-radius:3px;height:20px;position:relative"><div style="width:${Math.min(b.width / 2, 100)}%;max-width:100%;background:${b.color};border-radius:3px;height:100%;display:flex;align-items:center;padding-left:6px"><span style="font-size:10px;color:#fff;font-weight:600">~${b.label === `${value}rem` ? (value * rootSize).toFixed(0) : pxValue}px</span></div></div></div>`).join("");const preview = `<div><div style="font-size:12px;font-weight:600;margin-bottom:10px;color:#374151">Root font: ${rootSize}px &rarr; ${value}${unit} &asymp; ${pxValue}px computed</div><div style="border:1px solid #e5e7eb;border-radius:8px;padding:14px;background:#f9fafb"><div style="font-size:11px;color:#6b7280;margin-bottom:8px">Width comparison (${rootSize}px root):</div>${bars}</div><div style="margin-top:8px;font-size:11px;color:#6b7280">${unit} is relative to the <strong>root element's</strong> font metrics. Unlike rem (relative to root font-size), ${unit} references the actual glyph measurements at the root.</div></div>`;return { output: lines.join("\n"), preview };}};